public static int findNthLeapYear(int Y, int N) {
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Both Y and N must be positive integers.");
    }

    int count = 0;
    int year = Y + 1;

    while (count < N) {
        if (isLeapYear(year)) {
            count++;
            if (count == N) {
                return year;
            }
        }
        year++;
    }

    return -1;
}

private static boolean isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

