public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Collect all unique substrings of all strings and their inverses
    java.util.Set<String> substrings = new java.util.HashSet<>();
    for (String s : strings) {
        if (s == null || s.isEmpty()) {
            continue;
        }
        // Add all substrings of s
        for (int i = 0; i < s.length(); i++) {
            for (int j = i + 1; j <= s.length(); j++) {
                substrings.add(s.substring(i, j));
            }
        }
    }

    // Find the largest substring that appears in some string or its inverse appears in some string
    int maxLen = 0;

    // To optimize, we can iterate over possible lengths from largest to smallest
    // But since we need to be efficient, let's just check all substrings we've collected
    // However, the number of substrings can be large, so we need a better approach.

    // Alternative approach: For each string, get all substrings.
    // For each candidate substring (from any string), check if it or its inverse is a substring of any of the input strings.
    // To avoid duplicate checks, we can use the set we built, but that set could be huge.

    // Let's use a different strategy:
    // 1. Find the maximum possible length across all strings.
    // 2. For each length from max down to 1, generate all possible substrings of that length from all strings.
    // 3. For each such substring, check if it or its inverse is a substring of any of the given strings.
    // 4. Return the first length for which we find a valid substring.

    int maxStrLen = 0;
    for (String s : strings) {
        if (s != null) {
            maxStrLen = Math.max(maxStrLen, s.length());
        }
    }

    // Create a list of non-null, non-empty strings for efficient substring checking
    List<String> validStrings = new java.util.ArrayList<>();
    for (String s : strings) {
        if (s != null && !s.isEmpty()) {
            validStrings.add(s);
        }
    }

    // For each length from max down to 1
    for (int len = maxStrLen; len >= 1; len--) {
        // Collect all substrings of this length from all strings
        java.util.Set<String> candidates = new java.util.HashSet<>();
        for (String s : validStrings) {
            if (s.length() >= len) {
                for (int i = 0; i <= s.length() - len; i++) {
                    candidates.add(s.substring(i, i + len));
                }
            }
        }

        // Check each candidate
        for (String candidate : candidates) {
            String inverse = new StringBuilder(candidate).reverse().toString();
            if (hasSubstring(validStrings, candidate) || hasSubstring(validStrings, inverse)) {
                return len;
            }
        }
    }

    return 0;
}

private boolean hasSubstring(List<String> strings, String target) {
    if (target == null || target.isEmpty()) {
        return true;
    }
    for (String s : strings) {
        if (s == null) {
            continue;
        }
        if (s.contains(target)) {
            return true;
        }
    }
    return false;
}
