public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    // Build adjacency list
    int[][] adjacency = new int[n * n][n * n];
    int[] degree = new int[n * n];

    for (int[] path : paths) {
        if (path != null && path.length >= 2) {
            int u1 = path[0];
            int v1 = path[1];
            // Convert (x, y) to linear index
            int u = u1 * n + v1;
            // For undirected graph
            int u2 = path[0];
            int v2 = path[1];
            int v = u2 * n + v2;

            adjacency[u][degree[u]++] = v;
            adjacency[v][degree[v]++] = u;
        }
    }

    int startIdx = start[0] * n + start[1];
    int endIdx = end[0] * n + end[1];

    // Check if start and end are valid
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n) {
        return "cannot be travelled";
    }
    if (end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // BFS
    boolean[] visited = new boolean[n * n];
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    queue.offer(startIdx);
    visited[startIdx] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == endIdx) {
            return "can be travelled";
        }
        for (int i = 0; i < degree[current]; i++) {
            int neighbor = adjacency[current][i];
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}
