public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        // Edge case: empty string or string shorter than k
        // Cannot contain all 2^k codes
        // If k is 0, there is exactly one binary string of length 0, which is the empty string.
        // But problem likely implies k >= 1. Let's handle k=0 explicitly.
        if (k == 0) {
            return true;
        }
        return false;
    }

    // If k is negative, it's invalid input, but let's assume k >= 1 based on problem context.
    if (k < 0) {
        return false;
    }

    // The number of unique binary strings of length k is 2^k
    int totalUniqueCodes = (int) Math.pow(2, k);

    // If the string is too short to possibly contain all unique codes
    // The number of substrings of length k in s is s.length() - k + 1
    if (s.length() - k + 1 < totalUniqueCodes) {
        return false;
    }

    // Use a boolean array to track which codes have been seen
    boolean[] seen = new boolean[totalUniqueCodes];

    // Sliding window approach
    // Initialize the first window of length k
    int code = 0;
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen[code] = true;
    int uniqueCount = 1;

    // Slide the window
    for (int i = k; i < s.length(); i++) {
        // Remove the most significant bit (the character falling out of the window)
        // Shift left, and then mask to keep only k bits
        code = ((code << 1) & ((1 << k) - 1)) | (s.charAt(i) - '0');

        if (!seen[code]) {
            seen[code] = true;
            uniqueCount++;

            // Early termination if we've seen all unique codes
            if (uniqueCount == totalUniqueCodes) {
                return true;
            }
        }
    }

    return uniqueCount == totalUniqueCodes;
}
