            int next = fibs.get(i - 1) + fibs.get(i - 2);
            if (next > k) {
                break;
            }
            fibs.add(next);
            i++;
        }

        // Greedy approach: pick the largest Fibonacci number <= remaining k
        int count = 0;
        int idx = fibs.size() - 1;
        while (k > 0 && idx >= 0) {
            if (fibs.get(idx) <= k) {
                k -= fibs.get(idx);
                count++;
            }
            idx--;
        }

        return count;
    }
