public int maxUniqueSplit(String s) {
    return backtrack(s, 0, new java.util.HashSet<>());
}

private int backtrack(String s, int index, java.util.HashSet<String> used) {
    if (index == s.length()) {
        return 0;
    }
    int max = 0;
    for (int i = index; i < s.length(); i++) {
        String substring = s.substring(index, i + 1);
        if (!used.contains(substring)) {
            used.add(substring);
            int count = 1 + backtrack(s, i + 1, used);
            max = Math.max(max, count);
            used.remove(substring);
        }
    }
    return max;
}
