public String getSmallestString(int n, int k) {
    if (n <= 0 || k <= 0 || k > 26 * n) {
        throw new IllegalArgumentException("Invalid input: n and k must be positive, and k must not exceed 26 * n");
    }

    char[] result = new char[n];

    // We need to assign 'a' (value 1) to as many characters as possible from left to right.
    // The last character must take the remaining value.
    // Let's say we assign 'a' to the first (n-1) characters, then the last character would have value k - (n-1)*1.
    // But the last character must be between 1 and 26. So if the remaining value is > 26, we need to adjust.

    // Better approach: we want to keep the prefix as small as possible (all 'a'), and put the excess in the rightmost positions.
    // The minimal value for a string of length n is n (all 'a's).
    // The excess value is k - n.
    // We need to distribute this excess to the rightmost characters, each character can take at most 25 extra (from 'a'=1 to 'z'=26).

    int excess = k - n;
    int maxExtraPerChar = 25;

    // We'll work from right to left, which is equivalent to finding the smallest lex string.
    // Actually, to get the lexicographically smallest string, we want the leftmost characters to be as small as possible.
    // So we should put the excess on the rightmost characters.

    // Start with all 'a's
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    // Now distribute the excess from right to left
    int i = n - 1;
    while (i >= 0 && excess > 0) {
        int give = Math.min(excess, maxExtraPerChar);
        result[i] = (char) ('a' + 1 + give - 1); // 'a' + give
        excess -= give;
        i--;
    }

    return new String(result);
}
