            result.add(num);
        }
        if (num > high) continue;

        int lastDigit = num % 10;
        if (lastDigit > 0) {
            int next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            int next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }

    return result;
}
