public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }

    int count = 0;
    long divisor = 1;
    long lowPart = 0;
    long midPart = 0;
    long highPart = 0;

    while (divisor <= n) {
        highPart = n / (divisor * 10);
        midPart = (n / divisor) % 10;
        lowPart = n - (n / divisor) * divisor;

        if (midPart == 0) {
            count += highPart * divisor;
        } else if (midPart == 1) {
            count += highPart * divisor + lowPart + 1;
        } else {
            count += (highPart + 1) * divisor;
        }

        divisor *= 10;
    }

    return count;
}
