public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    int[] count = new int[17];
    for (int num : A) {
        count[num]++;
    }

    int totalDistinct = 0;
    for (int c : count) {
        if (c > 0) totalDistinct++;
    }

    if (totalDistinct == 0) return 0;

    int[] distinctNums = new int[totalDistinct];
    int idx = 0;
    for (int i = 0; i < 17; i++) {
        if (count[i] > 0) {
            distinctNums[idx++] = i;
        }
    }

    boolean[][] isSquarePair = new boolean[17][17];
    for (int i = 0; i < 17; i++) {
        for (int j = 0; j < 17; j++) {
            int sum = i + j;
            int sqrt = (int) Math.sqrt(sum);
            isSquarePair[i][j] = (sqrt * sqrt == sum);
        }
    }

    int[] used = new int[17];
    return backtrack(distinctNums, count, used, n, 0, isSquarePair);
}

private static int backtrack(int[] distinctNums, int[] count, int[] used, int n, int pos, boolean[][] isSquarePair) {
    if (pos == n) {
        return 1;
    }

    int result = 0;
    Integer lastUsedNumber = null;
    // Track the last placed number to check adjacency
    // We need to know what the last element in the current permutation is
    // But we don't have that directly. Instead, we can pass it through.
    // Let's refactor: we need to know the last number placed.

    // Actually, let's redo with lastNum passed.
    return backtrackHelper(distinctNums, count, used, n, pos, isSquarePair, null);
}

private static int backtrackHelper(int[] distinctNums, int[] count, int[] used, int n, int pos, boolean[][] isSquarePair, Integer lastNum) {
    if (pos == n) {
        return 1;
    }

    int result = 0;
    boolean[] seen = new boolean[17];

    for (int num : distinctNums) {
        if (count[num] <= 0) continue;
        if (seen[num]) continue;

        // Check if this number can be placed at position pos
        if (lastNum != null) {
            int ls = lastNum;
            if (!isSquarePair[ls][num]) {
                continue;
            }
        }

        seen[num] = true;
        count[num]--;
        result += backtrackHelper(distinctNums, count, used, n, pos + 1, isSquarePair, num);
        count[num]++;
    }

    return result;
}
