    public static int largestRectangleArea(int[] heights) {
        if (heights == null || heights.length == 0) {
            return 0;
        }

        int n = heights.length;
        int maxArea = 0;
        int[] left = new int[n];
        int[] right = new int[n];
        int[] stack = new int[n];
        int top = -1;

        // Calculate the index of the nearest bar with a smaller height to the left
        for (int i = 0; i < n; i++) {
            while (top >= 0 && heights[stack[top]] >= heights[i]) {
                top--;
            }
            left[i] = (top == -1) ? -1 : stack[top];
            stack[++top] = i;
        }

        top = -1;
        // Calculate the index of the nearest bar with a smaller height to the right
        for (int i = n - 1; i >= 0; i--) {
            while (top >= 0 && heights[stack[top]] >= heights[i]) {
                top--;
            }
            right[i] = (top == -1) ? n : stack[top];
            stack[++top] = i;
        }

        // Calculate the maximum area of the rectangle
        for (int i = 0; i < n; i++) {
            int width = right[i] - left[i] - 1;
            int area = heights[i] * width;
            maxArea = Math.max(maxArea, area);
        }

        return maxArea;
    }
