public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int totalElements = rows * cols;
    int[] result = new int[totalElements];

    int resultIndex = 0;
    // There are rows + cols - 1 diagonals
    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            // Even diagonals: traverse from bottom to top
            int row = Math.min(d, rows - 1);
            int col = d - row;
            while (row >= 0 && col < cols) {
                result[resultIndex++] = mat[row][col];
                row--;
                col++;
            }
        } else {
            // Odd diagonals: traverse from top to bottom
            int col = Math.min(d, cols - 1);
            int row = d - col;
            while (row < rows && col >= 0) {
                result[resultIndex++] = mat[row][col];
                row++;
                col--;
            }
        }
    }

    return result;
}
