public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;

    // Find the rightmost digit that is smaller than the digit immediately after it
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit exists, the digits are in non-increasing order
    // which means no rearrangement can be greater than n
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit on the right side of i that is still greater than digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the two digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the suffix after position i to get the smallest possible rearrangement
    if (digits[i] < 0 || digits[i] > 9) {
        return -1;
    }

    // Reverse the digits after position i
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }

    // Convert back to integer, handling potential overflow
    StringBuilder sb = new StringBuilder();
    sb.append(digits);
    try {
        int result = Integer.parseInt(sb.toString());
        // Check if the result is indeed greater than n and within int range
        if (result > n) {
            return result;
        }
    } catch (NumberFormatException e) {
        // If overflow occurred, the result is too large
        return -1;
    }

    return -1;
}
