public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    // Check if any two points are identical
    if (isSamePoint(points[0], points[1]) || isSamePoint(points[1], points[2]) || isSamePoint(points[0], points[2])) {
        return false;
    }
    // Check if the three points are collinear using cross product
    // If (P1 - P0) x (P2 - P0) == 0, they are collinear
    long dx1 = points[1][0] - points[0][0];
    long dy1 = points[1][1] - points[0][1];
    long dx2 = points[2][0] - points[0][0];
    long dy2 = points[2][1] - points[0][1];
    long cross = dx1 * dy2 - dx2 * dy1;
    return cross != 0;
}

private static boolean isSamePoint(int[] p1, int[] p2) {
    return p1[0] == p2[0] && p1[1] == p2[1];
}
