public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }

    int[] dp = new int[n];
    dp[0] = 1;

    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;

    for (int i = 1; i < n; i++) {
        int min = Math.min(next2, Math.min(next3, next5));
        dp[i] = min;

        if (min == next2) {
            i2++;
            next2 = dp[i2] * 2;
        }
        if (min == next3) {
            i3++;
            next3 = dp[i3] * 3;
        }
        if (min == next5) {
            i5++;
            next5 = dp[i5] * 5;
        }
    }

    return dp[n - 1];
}
