public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    int current = 1;

    for (int i = 0; i < n; i++) {
        result.add(current);

        if (current * 10 <= n) {
            current = current * 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current = current + 1;
        }
    }

    return result;
